import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"59、【渙】 坎下巽上","description":"周易口訣義 - 59、【渙】 坎下巽上","frontmatter":{"title":"59、【渙】 坎下巽上","description":"周易口訣義 - 59、【渙】 坎下巽上"},"headers":[],"relativePath":"classics/koujueyi/061.md","filePath":"classics/koujueyi/061.md"}'),r={name:"classics/koujueyi/061.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_59、【渙】-坎下巽上" tabindex="-1">59、【渙】 坎下巽上 <a class="header-anchor" href="#_59、【渙】-坎下巽上" aria-label="Permalink to “59、【渙】 坎下巽上”">​</a></h1><p>彖曰：「渙亨」，剛來而不窮，柔得位乎外而上同。「王假有廟」，王乃在中也。「利涉大川」，乘木有功也。</p><p>象曰：風行水上，「渙」。先王以享於帝，立廟。</p><p>初六：用拯馬壯，吉。</p><p>象曰：初六之吉，順也。</p><p>九二，渙奔其機，悔亡。</p><p>象曰：「渙奔其機」，得願也。</p><p>六三，渙其躬，無悔。</p><p>象曰：「渙其躬」，志在外也。</p><p>六四，渙其群，元吉。渙有丘，匪夷所思。</p><p>象曰：「渙其群元吉」，光大也。</p><p>九五，渙汗其大號。渙，王居無咎。</p><p>象曰：「王居無咎」，正位也。</p><p>上九，渙其血，去逖出，無咎。</p><p>象曰：「渙其血」，遠害也。</p><p>解讀</p><p>「渙亨，王假有廟」者，渙者，離散之名，緩釋為義。然則小人遭難，奔走逃散，逃散方始獲濟。大德之人，處難之時，能建功立德，散釋險難，以安時人，故謂之「渙」也。能釋險難，人皆獲濟，所以亨通。王能釋難而通，天下太平，至於建立宗廟，德洽人神，雖復大川，亦可濟涉。險難既釋，宜弘道化，利物聚人，莫過於正，故曰「利涉大川，利貞」也。象曰「風行水上，渙」者，風行水上，激揚波濤，散釋之象。「先王以享於帝，立廟」者，先王既釋險難，民泰時安，可以享獻上帝，建立宗廟，祭祀祖考，告以太平也。</p><p>「初六，用拯馬壯，吉」者，拯，拔也；初六處難之初，乖散未甚，可以用馬拯拔，得其志而遠難，難初未至危劇，相時而行，是壯而獲吉也。</p><p>「九二，渙奔其機，悔亡」者，機是案機以承物也，謂初與二俱無應相得，既託於初，得其所安，逃難離散而奔，故曰「渙奔其機，悔亡」也。</p><p>「六三，渙其躬，無咎」者，渙之為義，內險外安，六三有應於外，不顧所守，脫身而出，與剛合志，故得悔亡，故曰「渙其躬，無悔」也。</p><p>「六四，渙其群，元吉，渙有丘，匪夷所思」者，六四既在險外，即是已險難之人，近於至尊，為君委任，內主樞密，外宣王命，而能散群眾之難，以安綏萬人也，而獲其大功，所以「元吉」，故「渙其群，元吉」。然為君所任，任重憂深，雖能散眾之難，猶疑散難之中，恐有未平丘墟之險，恆懷思慮，心未得安，故曰「渙有丘，匪夷所思」也。丘，丘墟也；夷，平也。</p><p>「九五，渙汗其大號，渙王居無咎」者，人之驚怖既汗從體流，故以訓釋為「汗」也。九五處於尊位而能發號施令，大散天下之險危，故曰「渙汗其大號」也。為渙之主，能散險難，若非王者正位則不能，然正位不可假人，故王居無咎也。</p><p>「上九：渙其血，去逖出，無咎」者，血，傷害之義；逖，遠也。上九所居最是險外，是不為物之侵傷，逖遠而去，拔出險外，故曰「渙其血」也。散患於遠害之地，誰能與我為咎也？</p>',23)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
